    # =============================================================================
    # HTTP / rate-limit tuning
    # =============================================================================

    DEFAULT_TIMEOUT = 30  # seconds; every request passes an explicit timeout

    # Retried with backoff. 429 is the "modern style" throttle; 403 is only
    # retried when the Mashery error header marks it as a throttle (see
    # egnyte_client.is_throttled) — a plain 403 is a permissions failure.
    RETRIABLE_STATUS_CODES = frozenset({429, 500, 502, 503, 504})
    MAX_RETRIES = 5
    INITIAL_BACKOFF = 1.0  # seconds, doubled per retry

    # Legacy throttle signalling: 403 + X-Mashery-Error-Code.
    MASHERY_ERROR_HEADER = "X-Mashery-Error-Code"
    MASHERY_THROTTLE_CODES = (
        "ERR_403_DEVELOPER_OVER_QPS",
        "ERR_403_DEVELOPER_OVER_RATE",
    )

    # Proactive QPS headroom headers. When current is at/above allotted we sleep
    # briefly rather than earning a 403/429.
    QPS_CURRENT_HEADER = "X-Accesstoken-Qps-Current"
    QPS_ALLOTTED_HEADER = "X-Accesstoken-Qps-Allotted"
    QPS_COOLDOWN_SECONDS = 1.0

    # Standard quota is 2 calls/second/token. Space calls out so a tree walk or a
    # wide partition fan-out does not trip the per-second limit on its own.
    DEFAULT_MIN_REQUEST_INTERVAL = 0.5  # seconds between requests on one client

    # The OAuth token endpoint is capped at 100 requests/hour and answers 409
    # (not 429) when throttled.
    OAUTH_THROTTLE_STATUS = 409


    # =============================================================================
    # Read tuning defaults (all overridable through table_options)
    # =============================================================================

    # Filesystem tree walk.
    DEFAULT_ROOT_PATHS = "/Shared"
    DEFAULT_FS_PAGE_SIZE = 100
    DEFAULT_MAX_DEPTH = 20

    # SCIM list endpoints cap page size at 100.
    DEFAULT_SCIM_PAGE_SIZE = 100
    MAX_SCIM_PAGE_SIZE = 100

    # Links: docs allow up to 500 per request.
    DEFAULT_LINKS_PAGE_SIZE = 100
    MAX_LINKS_PAGE_SIZE = 500
    DEFAULT_LINKS_WINDOW_DAYS = 7

    # Events.
    DEFAULT_EVENTS_PAGE_SIZE = 100
    DEFAULT_EVENTS_API_VERSION = "v1"

    # Audit reporting v1.
    DEFAULT_AUDIT_WINDOW_DAYS = 7
    DEFAULT_AUDIT_BACKFILL_DAYS = 7
    DEFAULT_AUDIT_PAGE_SIZE = 100
    # Official guidance: poll the job endpoint no more than once every 2 minutes.
    DEFAULT_AUDIT_POLL_INTERVAL_SECONDS = 120
    DEFAULT_AUDIT_POLL_MAX_ATTEMPTS = 30
    DEFAULT_AUDIT_LOGIN_EVENTS = ("successful_login", "failed_attempts")
    # `permissions` reports require all four filter keys per the SDK signature.
    DEFAULT_AUDIT_PERMISSION_FOLDERS = ("/Shared",)
    AUDIT_RUNNING_STATUSES = frozenset(
        {"running", "in_progress", "in progress", "pending", "queued", "started"}
    )

    # Hard stop for every pagination loop. Egnyte's pagination metadata is
    # inconsistent across resources (the v2 links list's field names are
    # UNVERIFIED in the doc), so each loop also carries an absolute page ceiling
    # rather than trusting the server to eventually return a short page.
    MAX_PAGES_PER_READ = 1000

    # Generic microbatch admission control for the single-driver read_table path.
    DEFAULT_MAX_RECORDS_PER_BATCH = 5000
    DEFAULT_MAX_PARTITIONS_PER_BATCH = 1


    ########################################################
    # src/databricks/labs/community_connector/sources/egnyte/egnyte_client.py
    ########################################################

    _LOG = logging.getLogger(__name__)


    class EgnyteApiError(RuntimeError):
        """Non-retriable error response from the Egnyte API."""

        def __init__(self, status_code: int, message: str, url: str) -> None:
            super().__init__(f"Egnyte API error {status_code} for {url}: {message}")
            self.status_code = status_code
            self.url = url


    # ---------------------------------------------------------------------------
    # URL / path helpers
    # ---------------------------------------------------------------------------


    def resolve_base_url(domain: str) -> str:
        """Turn a tenant identifier into the API base URL.

        The doc is explicit that the domain is a required per-tenant config value
        with no discovery path. Mirrors the official SDK's ``Session.__init__``:
        a bare label gets ``.egnyte.com`` appended, anything already containing a
        dot is used verbatim (custom-branded hostnames), and a full URL is
        accepted as-is.
        """
        value = (domain or "").strip().rstrip("/")
        if not value:
            raise ValueError(
                "Egnyte connector requires the 'domain' option (tenant subdomain, "
                "e.g. 'acmecorp', or a full custom hostname)"
            )
        if value.startswith(("http://", "https://")):
            return value
        if "." in value:
            return f"https://{value}"
        return f"https://{value}.egnyte.com"


    def encode_fs_path(path: str) -> str:
        """Percent-encode a filesystem path one segment at a time.

        Known quirk: each segment must be encoded individually and the ``/``
        separators must stay literal, so
        ``Shared/example?path/$file.txt`` becomes
        ``Shared/example%3Fpath/%24file.txt``.
        """
        segments = [seg for seg in (path or "").split("/") if seg]
        return "/".join(quote(seg, safe="") for seg in segments)


    def normalize_fs_path(path: str) -> str:
        """Canonicalize a filesystem path to a leading-slash, no-trailing-slash form."""
        stripped = (path or "").strip().strip("/")
        return f"/{stripped}" if stripped else "/"


    def extract_error_message(response: requests.Response) -> str:
        """Best-effort decode of Egnyte's two documented error envelopes.

        Shape A (best-practices page):  ``{"Errors": [{"description": ..., "code": ...}]}``
        Shape B (implied by the SDK):   ``{"errors": {"inputErrors": [{"message": ...}]}}``

        The doc flags the casing inconsistency explicitly, so both are checked
        and anything unrecognized falls back to the raw body.
        """
        try:
            body = response.json()
        except ValueError:
            return (response.text or "")[:500]

        messages: list[str] = []

        def _collect(node: Any) -> None:
            if isinstance(node, dict):
                for key in ("description", "message", "error", "reason"):
                    value = node.get(key)
                    if isinstance(value, str):
                        messages.append(value)
                for key in ("inputErrors", "errors", "Errors"):
                    if key in node:
                        _collect(node[key])
            elif isinstance(node, list):
                for item in node:
                    _collect(item)

        if isinstance(body, dict):
            for key in ("Errors", "errors"):
                if key in body:
                    _collect(body[key])
            if not messages:
                _collect(body)

        if messages:
            return "; ".join(dict.fromkeys(messages))
        return (response.text or "")[:500]


    def is_throttled(response: requests.Response) -> bool:
        """True when the response is a throttle signal in either documented style."""
        if response.status_code == 429:
            return True
        if response.status_code == 403:
            code = response.headers.get(MASHERY_ERROR_HEADER, "")
            return any(marker in code for marker in MASHERY_THROTTLE_CODES)
        return False


    def retry_after_seconds(response: requests.Response, fallback: float) -> float:
        """Read ``Retry-After`` (seconds form), falling back to the caller's backoff."""
        raw = response.headers.get("Retry-After")
        if not raw:
            return fallback
        try:
            return max(0.0, float(raw))
        except (TypeError, ValueError):
            return fallback


    # ---------------------------------------------------------------------------
    # Client
    # ---------------------------------------------------------------------------


    class EgnyteClient:
        """Thin ``requests`` wrapper that owns auth, retries, and throttle handling.

        Constructed lazily by the connector (and re-constructed on each Spark
        executor) so no live socket ever has to survive pickling.
        """

        def __init__(
            self,
            base_url: str,
            access_token: str,
            *,
            timeout: int = DEFAULT_TIMEOUT,
            min_request_interval: float = DEFAULT_MIN_REQUEST_INTERVAL,
        ) -> None:
            self.base_url = base_url.rstrip("/")
            self.timeout = timeout
            self.min_request_interval = max(0.0, min_request_interval)
            self._last_request_at = 0.0
            self._session = requests.Session()
            self._session.headers.update(
                {
                    "Accept": "application/json",
                    "Authorization": f"Bearer {access_token}",
                }
            )

        # -- low level ---------------------------------------------------------

        def _throttle_gate(self) -> None:
            """Space consecutive calls so we stay under the 2 QPS token ceiling."""
            if self.min_request_interval <= 0:
                return
            elapsed = time.monotonic() - self._last_request_at
            if 0 <= elapsed < self.min_request_interval:
                time.sleep(self.min_request_interval - elapsed)

        @staticmethod
        def _qps_cooldown(response: requests.Response) -> None:
            """Pause when the QPS headroom headers say we are at the allotment."""
            current = response.headers.get(QPS_CURRENT_HEADER)
            allotted = response.headers.get(QPS_ALLOTTED_HEADER)
            if not current or not allotted:
                return
            try:
                if float(current) >= float(allotted):
                    time.sleep(QPS_COOLDOWN_SECONDS)
            except (TypeError, ValueError):
                return

        def request(
            self,
            method: str,
            url: str,
            *,
            params: Mapping[str, Any] | None = None,
            json_body: Any = None,
            allow_redirects: bool = True,
            expected: Iterable[int] = (200,),
        ) -> requests.Response:
            """Issue one request with throttle-aware retries.

            Returns the response whenever its status is in ``expected``; raises
            ``EgnyteApiError`` otherwise. Retriable statuses (429/5xx and
            throttle-flavoured 403s) are retried with ``Retry-After``-aware
            exponential backoff before the final failure is raised.
            """
            expected_codes = set(expected)
            backoff = INITIAL_BACKOFF
            response: requests.Response | None = None

            for attempt in range(MAX_RETRIES):
                self._throttle_gate()
                response = self._session.request(
                    method,
                    url,
                    params=params,
                    json=json_body,
                    timeout=self.timeout,
                    allow_redirects=allow_redirects,
                )
                self._last_request_at = time.monotonic()

                if response.status_code in expected_codes:
                    self._qps_cooldown(response)
                    return response

                throttled = is_throttled(response)
                retriable = throttled or response.status_code in RETRIABLE_STATUS_CODES
                if not retriable or attempt == MAX_RETRIES - 1:
                    break

                wait = retry_after_seconds(response, backoff)
                _LOG.warning(
                    "Egnyte %s %s returned %s (%s) — retrying in %.1fs",
                    method,
                    url,
                    response.status_code,
                    "throttled" if throttled else "retriable",
                    wait,
                )
                time.sleep(wait)
                backoff *= 2

            assert response is not None  # loop always assigns at least once
            raise EgnyteApiError(
                response.status_code, extract_error_message(response), url
            )

        # -- convenience -------------------------------------------------------

        def url(self, path: str) -> str:
            return f"{self.base_url}/{path.lstrip('/')}"

        def get_json(
            self,
            path: str,
            *,
            params: Mapping[str, Any] | None = None,
            expected: Iterable[int] = (200,),
        ) -> dict:
            response = self.request("GET", self.url(path), params=params, expected=expected)
            return _json_or_empty(response)

        def get_raw(
            self,
            path: str,
            *,
            params: Mapping[str, Any] | None = None,
            expected: Iterable[int] = (200,),
            allow_redirects: bool = True,
        ) -> requests.Response:
            return self.request(
                "GET",
                self.url(path),
                params=params,
                expected=expected,
                allow_redirects=allow_redirects,
            )

        def post_json(
            self,
            path: str,
            *,
            json_body: Any = None,
            expected: Iterable[int] = (200, 201, 202),
        ) -> dict:
            response = self.request(
                "POST", self.url(path), json_body=json_body, expected=expected
            )
            return _json_or_empty(response)


    def _json_or_empty(response: requests.Response) -> dict:
        """Parse a JSON body, tolerating the empty payloads Egnyte sends on 204."""
        if not (response.content or b"").strip():
            return {}
        try:
            body = response.json()
        except ValueError as exc:
            raise EgnyteApiError(
                response.status_code,
                f"response was not valid JSON: {exc}",
                response.url or "",
            ) from exc
        return body if isinstance(body, dict) else {"_list": body}


    # ---------------------------------------------------------------------------
    # OAuth
    # ---------------------------------------------------------------------------


    def fetch_access_token(
        base_url: str,
        client_id: str,
        client_secret: str,
        refresh_token: str,
        *,
        timeout: int = DEFAULT_TIMEOUT,
    ) -> str:
        """Exchange a stored refresh token for a fresh access token.

        This is the project-convention flow: the interactive authorization-code
        step happens once, out of band, and the connector only ever refreshes.
        Access tokens live 30 days, so one exchange per run is ample — which also
        keeps us well clear of the endpoint's 100-requests/hour cap.

        That cap answers ``409`` (not ``429``) when breached; both it and the
        ordinary retriable statuses are honoured here with ``Retry-After``.
        """
        url = f"{base_url.rstrip('/')}/puboauth/token"
        payload = {
            "client_id": client_id,
            "client_secret": client_secret,
            "grant_type": "refresh_token",
            "refresh_token": refresh_token,
        }
        backoff = INITIAL_BACKOFF
        response: requests.Response | None = None

        with requests.Session() as session:
            for attempt in range(MAX_RETRIES):
                response = session.post(url, data=payload, timeout=timeout)
                if response.status_code == 200:
                    break
                retriable = (
                    response.status_code == OAUTH_THROTTLE_STATUS
                    or is_throttled(response)
                    or response.status_code in RETRIABLE_STATUS_CODES
                )
                if not retriable or attempt == MAX_RETRIES - 1:
                    break
                wait = retry_after_seconds(response, backoff)
                _LOG.warning(
                    "Egnyte token endpoint returned %s — retrying in %.1fs",
                    response.status_code,
                    wait,
                )
                time.sleep(wait)
                backoff *= 2

        assert response is not None
        if response.status_code != 200:
            raise EgnyteApiError(
                response.status_code, extract_error_message(response), url
            )

        body = _json_or_empty(response)
        token = body.get("access_token")
        if not token:
            raise EgnyteApiError(
                response.status_code,
                "token response did not contain an 'access_token'",
                url,
            )
        return str(token)


    ########################################################
    # src/databricks/labs/community_connector/sources/egnyte/egnyte_utils.py
    ########################################################

    ISO_FMT = "%Y-%m-%dT%H:%M:%SZ"
    DATE_FMT = "%Y-%m-%d"
    EPOCH_ISO = "1970-01-01T00:00:00Z"
    # A resumed cursor at or below this is "never read anything yet", which the
    # range readers serve with one open-ended partition instead of ~55 years of
    # empty windows.
    FIRST_RUN_THRESHOLD_ISO = "1971-01-01T00:00:00Z"


    def records_from(body: dict, candidate_keys: tuple[str, ...]) -> list:
        """Pull the record array out of a response whose wrapper key varies.

        The v2 links list's pagination-metadata field names are UNVERIFIED in the
        API doc, so the wrapper key is probed rather than assumed. A bare JSON
        array is also accepted (``EgnyteClient`` parks one under ``_list``).
        """
        for key in candidate_keys:
            value = body.get(key)
            if isinstance(value, list):
                return value
        value = body.get("_list")
        return value if isinstance(value, list) else []


    def csv_option(raw: str | None, default: Sequence[str]) -> list[str]:
        """Split a comma-separated table option into a list, or fall back."""
        if raw is None or not raw.strip():
            return list(default)
        return [part.strip() for part in raw.split(",") if part.strip()]


    def parse_bool(raw: Any) -> bool:
        if isinstance(raw, bool):
            return raw
        return str(raw).strip().lower() in ("1", "true", "yes", "y", "on")


    def parse_int(raw: Any, default: int, *, minimum: int = 0) -> int:
        try:
            value = int(raw)
        except (TypeError, ValueError):
            return default
        return value if value >= minimum else default


    def parse_float(raw: Any, default: float) -> float:
        try:
            value = float(raw)
        except (TypeError, ValueError):
            return default
        return value if value >= 0 else default


    def parse_optional_int(raw: Any) -> int | None:
        if raw is None or isinstance(raw, bool):
            return None
        try:
            return int(raw)
        except (TypeError, ValueError):
            return None


    def parse_iso(value: str) -> datetime:
        """Parse an ISO-8601 timestamp into an aware UTC datetime.

        Tolerates the ``Z`` suffix, an explicit offset, a naive value (assumed
        UTC), and a bare date — the doc warns that timestamp spellings differ
        between Egnyte endpoints.
        """
        text = str(value).strip()
        if text.endswith("Z"):
            text = f"{text[:-1]}+00:00"
        try:
            parsed = datetime.fromisoformat(text)
        except ValueError as exc:
            raise ValueError(f"Cannot parse {value!r} as an ISO-8601 timestamp") from exc
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)


    def parse_optional_iso(value: Any) -> datetime | None:
        if not isinstance(value, str) or not value.strip():
            return None
        try:
            return parse_iso(value)
        except ValueError:
            return None


    def format_iso(value: datetime) -> str:
        return value.astimezone(timezone.utc).strftime(ISO_FMT)


    def api_timestamp(value: datetime) -> str:
        """Render a timestamp for Egnyte's v2 query params.

        Uses the explicit ``+00:00`` offset form the links API documents. Passing
        it through requests' ``params`` percent-encodes the ``+`` as ``%2B``,
        which is exactly the encoding the doc calls out as a gotcha.
        """
        return value.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S+00:00")


    def parse_date(value: str) -> date:
        return datetime.strptime(str(value).strip()[:10], DATE_FMT).date()


    def format_date(value: date) -> str:
        return value.strftime(DATE_FMT)


    def parent_path_of(path: str) -> str:
        """Derive a folder's parent path from its own canonical path."""
        trimmed = (path or "/").rstrip("/")
        if "/" not in trimmed[1:]:
            return "/"
        return trimmed.rsplit("/", 1)[0] or "/"


    ########################################################
    # src/databricks/labs/community_connector/sources/egnyte/egnyte_audit.py
    ########################################################

    def read_audit_window(
        client: EgnyteClient,
        domain: str,
        audit_type: str,
        date_start: str,
        date_end: str,
        table_options: dict[str, str],
    ) -> Iterator[dict]:
        """Run one full report lifecycle for an inclusive ``date_start..date_end``."""
        job_id = create_job(client, audit_type, date_start, date_end, table_options)
        await_job(client, job_id, table_options)
        yield from fetch_report(client, domain, audit_type, job_id, table_options)


    def create_job(
        client: EgnyteClient,
        audit_type: str,
        date_start: str,
        date_end: str,
        table_options: dict[str, str],
    ) -> str:
        """Submit a report job and return its id.

        Each report type takes a different filter set. ``permissions`` is the
        fussy one: the SDK signature marks all four of ``folders``,
        ``assigners``, ``assignee_users`` and ``assignee_groups`` as required, so
        they are always sent (empty lists mean "no restriction").
        """
        body: dict[str, Any] = {
            "format": "json",
            "date_start": date_start,
            "date_end": date_end,
        }

        if audit_type == "logins":
            body["events"] = csv_option(
                table_options.get("audit_events"), DEFAULT_AUDIT_LOGIN_EVENTS
            )
        elif audit_type == "files":
            # All optional on this report type; only send what was configured.
            for option_key, field in (
                ("audit_folders", "folders"),
                ("audit_users", "users"),
                ("audit_transaction_types", "transaction_type"),
            ):
                values = csv_option(table_options.get(option_key), ())
                if values:
                    body[field] = values
            if table_options.get("audit_file"):
                body["file"] = table_options["audit_file"]
        else:  # permissions
            body["folders"] = csv_option(
                table_options.get("audit_folders"), DEFAULT_AUDIT_PERMISSION_FOLDERS
            )
            body["assigners"] = csv_option(table_options.get("audit_assigners"), ())
            body["assignee_users"] = csv_option(
                table_options.get("audit_assignee_users"), ()
            )
            body["assignee_groups"] = csv_option(
                table_options.get("audit_assignee_groups"), ()
            )

        endpoint = f"/pubapi/v1/audit/{audit_type}"
        response = client.post_json(endpoint, json_body=body)
        job_id = response.get("id") or response.get("job_id")
        if not job_id:
            raise EgnyteApiError(
                202,
                f"audit {audit_type} report job for {date_start}..{date_end} "
                f"returned no job id (body keys: {sorted(response)})",
                client.url(endpoint),
            )
        return str(job_id)


    def await_job(
        client: EgnyteClient, job_id: str, table_options: dict[str, str]
    ) -> None:
        """Poll until the report is ready, or give up after a bounded number of tries.

        Two completion signals are accepted. The documented one is ``303 See
        Other`` with a ``Location`` header — which is why redirects are not
        followed here, otherwise requests would resolve it away before we could
        see it. Some deployments instead answer ``200`` with a terminal
        ``status``; anything that is not explicitly a *running* status is treated
        as done.

        Official guidance is to poll no more than once every two minutes, which is
        the ``audit_poll_interval_seconds`` default.
        """
        interval = parse_int(
            table_options.get("audit_poll_interval_seconds"),
            DEFAULT_AUDIT_POLL_INTERVAL_SECONDS,
            minimum=0,
        )
        max_attempts = parse_int(
            table_options.get("audit_poll_max_attempts"),
            DEFAULT_AUDIT_POLL_MAX_ATTEMPTS,
            minimum=1,
        )
        endpoint = f"/pubapi/v1/audit/jobs/{job_id}"

        for attempt in range(max_attempts):
            response = client.get_raw(
                endpoint, expected=(200, 303), allow_redirects=False
            )
            if response.status_code == 303:
                return

            payload = response.json() if (response.content or b"").strip() else {}
            status = str(payload.get("status", "")).strip().lower()
            if status not in AUDIT_RUNNING_STATUSES:
                return

            if attempt < max_attempts - 1 and interval:
                time.sleep(interval)

        raise EgnyteApiError(
            504,
            f"audit report job {job_id} did not complete after {max_attempts} polls",
            client.url(endpoint),
        )


    def fetch_report(
        client: EgnyteClient,
        domain: str,
        audit_type: str,
        job_id: str,
        table_options: dict[str, str],
    ) -> Iterator[dict]:
        """Page through a completed report's rows."""
        page_size = parse_int(
            table_options.get("audit_page_size"), DEFAULT_AUDIT_PAGE_SIZE, minimum=1
        )
        endpoint = f"/pubapi/v1/audit/{audit_type}/{job_id}"
        offset = 0

        for _ in range(MAX_PAGES_PER_READ):
            body = client.get_json(
                endpoint, params={"offset": offset, "count": page_size}
            )
            batch = body.get("events") or []
            if not batch:
                break

            for raw in batch:
                record = dict(raw)
                record["egnyte_domain"] = domain
                yield record

            offset += len(batch)
            total = parse_optional_int(body.get("total_count"))
            if total is not None and offset >= total:
                break
            if len(batch) < page_size:
                break


    ########################################################
    # src/databricks/labs/community_connector/sources/egnyte/egnyte.py
    ########################################################

    _LOG = logging.getLogger(__name__)

    _TREE_TABLES = frozenset({TABLE_FILES, TABLE_FOLDERS})


    class EgnyteLakeflowConnect(LakeflowConnect, SupportsPartitionedStream):
        """LakeflowConnect implementation for the Egnyte Public API.

        Connection options:
            domain              (required) tenant subdomain (``acmecorp``), a full
                                custom hostname (``files.acme.com``), or a full URL.
            access_token        Pre-issued OAuth bearer token. When present the
                                refresh exchange is skipped.
            client_id           OAuth API key, used with client_secret +
            client_secret       refresh_token to mint an access token per run.
            refresh_token
            timeout             Per-request timeout in seconds (default 30).
            min_request_interval
                                Seconds between successive calls on one client
                                (default 0.5 — Egnyte allows 2 calls/sec/token).

        Common table options:
            max_records_per_batch      Soft microbatch cap on the single-driver
                                       path (default 5000).
            max_partitions_per_batch   Time windows consumed per single-driver
                                       microbatch for links/audit (default 1).

        Per-table options are documented on each ``_read_*`` method.
        """

        # ------------------------------------------------------------------ #
        # Construction
        # ------------------------------------------------------------------ #

        def __init__(self, options: dict[str, str]) -> None:
            super().__init__(options)

            self.base_url = resolve_base_url(options.get("domain", ""))
            self.domain = self._domain_label(self.base_url)

            self._client_id = options.get("client_id")
            self._client_secret = options.get("client_secret")
            self._refresh_token = options.get("refresh_token")
            self._access_token = options.get("access_token") or options.get("token")

            if not self._access_token and not (
                self._client_id and self._client_secret and self._refresh_token
            ):
                raise ValueError(
                    "Egnyte connector requires either 'access_token' (a pre-issued "
                    "OAuth bearer token) or the trio 'client_id', 'client_secret' "
                    "and 'refresh_token' for the refresh-token flow"
                )

            self._timeout = parse_int(options.get("timeout"), DEFAULT_TIMEOUT, minimum=1)
            self._min_request_interval = parse_float(
                options.get("min_request_interval"), DEFAULT_MIN_REQUEST_INTERVAL
            )

            # Termination guard. Offsets never advance past this snapshot, so a
            # Trigger.AvailableNow run drains only what existed when it started.
            now = datetime.now(timezone.utc)
            self._init_time = format_iso(now)
            # Audit reports are requested by whole calendar day; capping at
            # midnight keeps every ingested window complete and non-overlapping.
            self._audit_cap_date = format_date(now.date())

        def __getstate__(self) -> dict:
            """Drop the live HTTP client before Spark pickles us to an executor.

            The resolved ``_access_token`` *is* kept, so executors reuse the
            driver's token instead of each re-hitting the 100/hour token endpoint.
            """
            state = dict(self.__dict__)
            state.pop("_client_obj", None)
            return state

        @property
        def _client(self) -> EgnyteClient:
            client = self.__dict__.get("_client_obj")
            if client is None:
                client = EgnyteClient(
                    self.base_url,
                    self._ensure_access_token(),
                    timeout=self._timeout,
                    min_request_interval=self._min_request_interval,
                )
                self.__dict__["_client_obj"] = client
            return client

        def _ensure_access_token(self) -> str:
            """Return a bearer token, exchanging the refresh token once if needed."""
            if self._access_token:
                return self._access_token
            self._access_token = fetch_access_token(
                self.base_url,
                self._client_id or "",
                self._client_secret or "",
                self._refresh_token or "",
                timeout=self._timeout,
            )
            return self._access_token

        @staticmethod
        def _domain_label(base_url: str) -> str:
            """Stable per-tenant label stamped onto every row."""
            try:
                return base_url.split("://", 1)[-1].split("/", 1)[0]
            except (AttributeError, IndexError):
                return base_url

        # ------------------------------------------------------------------ #
        # LakeflowConnect: discovery
        # ------------------------------------------------------------------ #

        def list_tables(self) -> list[str]:
            # Egnyte exposes no machine-readable object catalog; the set of
            # resource families is fixed and documented.
            return list(SUPPORTED_TABLES)

        def get_table_schema(
            self, table_name: str, table_options: dict[str, str]
        ) -> StructType:
            self._validate_table(table_name)
            return TABLE_SCHEMAS[table_name]

        def read_table_metadata(
            self, table_name: str, table_options: dict[str, str]
        ) -> dict:
            self._validate_table(table_name)
            return dict(TABLE_METADATA[table_name])

        def _validate_table(self, table_name: str) -> None:
            if table_name not in TABLE_SCHEMAS:
                raise ValueError(
                    f"Unsupported table {table_name!r}; supported: {SUPPORTED_TABLES}"
                )

        # ------------------------------------------------------------------ #
        # SupportsPartitionedStream
        # ------------------------------------------------------------------ #

        def is_partitioned(self, table_name: str) -> bool:
            """Only the range-queryable tables stream through executors."""
            return table_name in PARTITIONED_TABLES

        def latest_offset(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None = None,
        ) -> dict:
            """Return the high-water mark, capped at init time.

            Metadata only — no records are read here. The cap is what makes the
            offset stabilise so ``Trigger.AvailableNow`` terminates.
            """
            self._validate_table(table_name)
            if table_name in AUDIT_TABLE_TYPES:
                # Exclusive upper bound: everything strictly before today UTC.
                return {"date": self._audit_cap_date}
            if table_name == TABLE_LINKS:
                return {"cursor": self._init_time}
            if table_name == TABLE_EVENTS:
                latest = self._events_latest_id(table_options)
                return {"cursor": latest} if latest is not None else {}
            # Snapshot tables have no meaningful stream offset.
            return {}

        def get_partitions(
            self,
            table_name: str,
            table_options: dict[str, str],
            start_offset: dict | None = None,
            end_offset: dict | None = None,
        ) -> Sequence[dict]:
            """Split work into executor-sized units.

            With both offsets ``None`` this is a batch read and covers the whole
            table; with offsets it covers ``(start, end]`` only.
            """
            self._validate_table(table_name)

            if table_name in AUDIT_TABLE_TYPES:
                return self._audit_partitions(table_options, start_offset, end_offset)
            if table_name == TABLE_LINKS:
                return self._link_partitions(table_options, start_offset, end_offset)
            if table_name in _TREE_TABLES:
                # Batch-only: parallelise the recursive walk by subtree.
                return self._tree_partitions(table_options)
            # users / groups / events have no natural split — one unit of work.
            return [{"kind": "full"}]

        def read_partition(
            self, table_name: str, partition: dict, table_options: dict[str, str]
        ) -> Iterator[dict]:
            """Read one partition. Runs on an executor; must be self-contained."""
            self._validate_table(table_name)

            if table_name in AUDIT_TABLE_TYPES:
                yield from self._read_audit_window(table_name, partition, table_options)
            elif table_name == TABLE_LINKS:
                yield from self._read_links_window(
                    partition.get("since"), partition.get("until"), table_options
                )
            elif table_name in _TREE_TABLES:
                yield from self._read_tree_partition(table_name, partition, table_options)
            elif table_name == TABLE_USERS:
                yield from self._read_users(table_options)
            elif table_name == TABLE_GROUPS:
                yield from self._read_groups(table_options)
            elif table_name == TABLE_EVENTS:
                records, _ = self._read_events(None, table_options)
                yield from records
            else:  # pragma: no cover - _validate_table already guards this
                raise ValueError(f"Unsupported table: {table_name!r}")

        # ------------------------------------------------------------------ #
        # LakeflowConnect: single-driver read path
        # ------------------------------------------------------------------ #

        def read_table(
            self,
            table_name: str,
            start_offset: dict,
            table_options: dict[str, str],
        ) -> tuple[Iterator[dict], dict]:
            self._validate_table(table_name)

            # Snapshot tables stream lazily: a full tenant tree walk or user list
            # must not be materialised on the driver before the first row lands.
            if table_name in _TREE_TABLES:
                return (
                    self._read_tree_partition(
                        table_name, {"path": None, "recursive": True}, table_options
                    ),
                    {},
                )
            if table_name == TABLE_USERS:
                return self._read_users(table_options), {}
            if table_name == TABLE_GROUPS:
                return self._read_groups(table_options), {}
            if table_name == TABLE_EVENTS:
                return self._read_events(start_offset, table_options)
            return self._read_windowed_fallback(table_name, start_offset, table_options)

        def _read_windowed_fallback(
            self,
            table_name: str,
            start_offset: dict,
            table_options: dict[str, str],
        ) -> tuple[Iterator[dict], dict]:
            """Sequential single-driver equivalent of the partitioned stream.

            Used when the table is read through ``simpleStreamReader`` or an
            un-partitioned batch scan. Consumes at most
            ``max_partitions_per_batch`` windows per call (and stops early once
            ``max_records_per_batch`` is reached) so a microbatch stays bounded,
            then returns the offset at the last consumed window boundary.
            """
            start_offset = start_offset or {}
            end_offset = self.latest_offset(table_name, table_options)
            partitions = list(
                self.get_partitions(table_name, table_options, start_offset, end_offset)
            )
            if not partitions:
                # Nothing new — end_offset == start_offset makes the trigger stop.
                return iter([]), start_offset or end_offset

            max_partitions = parse_int(
                table_options.get("max_partitions_per_batch"),
                DEFAULT_MAX_PARTITIONS_PER_BATCH,
                minimum=1,
            )
            max_records = parse_int(
                table_options.get("max_records_per_batch"),
                DEFAULT_MAX_RECORDS_PER_BATCH,
                minimum=1,
            )

            records: list[dict] = []
            consumed: dict | None = None
            for partition in partitions[:max_partitions]:
                records.extend(self.read_partition(table_name, partition, table_options))
                consumed = partition
                # Append-only tables must never be truncated mid-window; we stop
                # taking *more* windows instead.
                if len(records) >= max_records:
                    break

            assert consumed is not None
            return iter(records), self._offset_after(table_name, consumed)

        @staticmethod
        def _offset_after(table_name: str, partition: dict) -> dict:
            """The checkpointable offset that follows a fully-consumed partition."""
            if table_name in AUDIT_TABLE_TYPES:
                # date_end is inclusive, so resume on the following day.
                end = parse_date(partition["date_end"]) + timedelta(days=1)
                return {"date": format_date(end)}
            return {"cursor": partition["until"]}

        # ------------------------------------------------------------------ #
        # Files & folders — recursive fs tree walk
        # ------------------------------------------------------------------ #
        #
        # Table options:
        #   root_paths     Comma-separated roots to walk (default "/Shared").
        #   fs_page_size   Items per folder listing page (default 100).
        #   max_depth      Recursion depth guard (default 20).
        #   include_perms  "true" adds the per-folder permissions block.
        #   include_locks  "true" adds file lock info.

        def _tree_partitions(self, table_options: dict[str, str]) -> list[dict]:
            """One partition per immediate subtree of each configured root.

            Costs one listing call per root on the driver. The root itself gets a
            non-recursive partition (its own record plus its direct files) so no
            subtree is walked twice.
            """
            partitions: list[dict] = []
            for root in self._root_paths(table_options):
                partitions.append({"path": root, "recursive": False})
                listing = self._fs_list(root, table_options)
                for child in listing.get("folders") or []:
                    child_path = child.get("path")
                    if child_path:
                        partitions.append({"path": child_path, "recursive": True})
            return partitions or [{"path": DEFAULT_ROOT_PATHS, "recursive": True}]

        def _read_tree_partition(
            self, table_name: str, partition: dict, table_options: dict[str, str]
        ) -> Iterator[dict]:
            """Walk one subtree and yield only the rows this table wants."""
            recursive = bool(partition.get("recursive", True))
            path = partition.get("path")
            roots = [path] if path else self._root_paths(table_options)
            wanted = "file" if table_name == TABLE_FILES else "folder"

            for root in roots:
                for kind, record in self._walk_tree(root, table_options, recursive):
                    if kind == wanted:
                        yield record

        def _walk_tree(
            self, root_path: str, table_options: dict[str, str], recursive: bool
        ) -> Iterator[tuple[str, dict]]:
            """Depth-first walk yielding ``("folder"|"file", record)`` pairs.

            There is no domain-wide "changed since" endpoint on the File System
            API, so every run re-walks the tree — hence the snapshot ingestion
            type. ``visited`` guards against symlink-ish cycles and against a
            malformed listing pointing back at an ancestor.
            """
            max_depth = parse_int(
                table_options.get("max_depth"), DEFAULT_MAX_DEPTH, minimum=0
            )
            stack: list[tuple[str, int, dict | None, str | None]] = [
                (root_path, 0, None, None)
            ]
            visited: set[str] = set()

            while stack:
                path, depth, stub, parent_path = stack.pop()
                canonical = normalize_fs_path(path)
                if canonical in visited:
                    continue
                visited.add(canonical)

                listing = self._fs_list(path, table_options)
                children = listing.pop("folders", None) or []
                files = listing.pop("files", None) or []

                if listing.get("is_folder") is False and not listing.get("folder_id"):
                    # The configured root turned out to be a file, not a folder.
                    yield "file", self._shape_file(
                        listing, parent_path or parent_path_of(canonical)
                    )
                    continue

                # The child stub from the parent listing is the only place
                # `lastModified` appears; the folder's own envelope wins on
                # everything else.
                merged = {**(stub or {}), **listing}
                yield "folder", self._shape_folder(
                    merged, parent_path or parent_path_of(canonical)
                )

                for record in files:
                    yield "file", self._shape_file(record, canonical)

                if not recursive or depth >= max_depth:
                    continue
                for child in children:
                    child_path = child.get("path")
                    if child_path:
                        stack.append((child_path, depth + 1, child, canonical))

        def _fs_list(self, path: str, table_options: dict[str, str]) -> dict:
            """Fetch one folder listing, merging every ``offset``/``count`` page.

            The envelope's ``folders``/``files`` arrays are concatenated across
            pages; scalar envelope fields come from the first page.
            """
            page_size = parse_int(
                table_options.get("fs_page_size"), DEFAULT_FS_PAGE_SIZE, minimum=1
            )
            base_params: dict[str, Any] = {"list_content": "true", "count": page_size}
            if parse_bool(table_options.get("include_perms")):
                base_params["perms"] = "true"
            if parse_bool(table_options.get("include_locks")):
                base_params["include_locks"] = "true"

            endpoint = f"/pubapi/v1/fs/{encode_fs_path(path)}"
            merged: dict[str, Any] | None = None
            offset = 0

            for _ in range(MAX_PAGES_PER_READ):
                params = {**base_params, "offset": offset}
                body = self._client.get_json(endpoint, params=params)
                if merged is None:
                    merged = {
                        k: v for k, v in body.items() if k not in ("folders", "files")
                    }
                    merged["folders"] = []
                    merged["files"] = []

                page_folders = body.get("folders") or []
                page_files = body.get("files") or []
                merged["folders"].extend(page_folders)
                merged["files"].extend(page_files)

                page_len = len(page_folders) + len(page_files)
                if page_len == 0:
                    break
                offset += page_len
                total = parse_optional_int(body.get("total_count"))
                if total is not None and offset >= total:
                    break
                if page_len < page_size:
                    break

            return merged or {}

        def _root_paths(self, table_options: dict[str, str]) -> list[str]:
            raw = table_options.get("root_paths") or DEFAULT_ROOT_PATHS
            paths = [normalize_fs_path(p) for p in raw.split(",") if p.strip()]
            return paths or [DEFAULT_ROOT_PATHS]

        def _shape_file(self, raw: dict, parent_path: str | None) -> dict:
            record = {k: v for k, v in raw.items() if k not in ("folders", "files")}
            record["parent_path"] = parent_path
            record["egnyte_domain"] = self.domain
            return record

        def _shape_folder(self, raw: dict, parent_path: str | None) -> dict:
            record = {k: v for k, v in raw.items() if k not in ("folders", "files")}
            record["parent_path"] = parent_path
            record["egnyte_domain"] = self.domain
            return record

        # ------------------------------------------------------------------ #
        # Users & groups — SCIM-style paging
        # ------------------------------------------------------------------ #
        #
        # Table options:
        #   page_size        Records per page, capped at 100 by the API.
        #   filter           Verbatim SCIM filter, e.g. 'email eq "a@b.com"'.
        #   include_members  groups only: fan out one GET per group for members.

        def _scim_pages(
            self, endpoint: str, table_options: dict[str, str]
        ) -> Iterator[dict]:
            """Yield records from a ``startIndex``/``count`` SCIM list endpoint.

            ``startIndex`` is 1-based. Paging stops on an empty page, once
            ``totalResults`` has been seen, or on a short page — whichever comes
            first, so a server that ignores or clamps the page size cannot spin
            this loop forever.
            """
            page_size = min(
                MAX_SCIM_PAGE_SIZE,
                parse_int(
                    table_options.get("page_size"), DEFAULT_SCIM_PAGE_SIZE, minimum=1
                ),
            )
            scim_filter = table_options.get("filter")

            start_index = 1
            seen = 0
            for _ in range(MAX_PAGES_PER_READ):
                params: dict[str, Any] = {"startIndex": start_index, "count": page_size}
                if scim_filter:
                    params["filter"] = scim_filter

                body = self._client.get_json(endpoint, params=params)
                resources = body.get("resources") or body.get("Resources") or []
                if not resources:
                    break

                yield from resources
                seen += len(resources)

                total = parse_optional_int(body.get("totalResults"))
                if total is not None and seen >= total:
                    break
                if len(resources) < page_size:
                    break
                start_index += len(resources)

        def _read_users(self, table_options: dict[str, str]) -> Iterator[dict]:
            """Full snapshot of ``/pubapi/v2/users``.

            The SCIM ``filter`` only supports exact ``eq`` on
            ``email``/``externalId``/``userName`` — there is no modified-since
            filter — so change detection is a full pull plus a downstream diff.
            """
            for raw in self._scim_pages("/pubapi/v2/users", table_options):
                record = dict(raw)
                record["egnyte_domain"] = self.domain
                yield record

        def _read_groups(self, table_options: dict[str, str]) -> Iterator[dict]:
            """Full snapshot of ``/pubapi/v2/groups``.

            The list endpoint returns only ``id`` and ``displayName``. Membership
            needs one ``GET /pubapi/v2/groups/{id}`` per group, which is an N+1
            fan-out against a 1,000-call/day quota — hence opt-in via
            ``include_members``.
            """
            include_members = parse_bool(table_options.get("include_members"))
            for raw in self._scim_pages("/pubapi/v2/groups", table_options):
                record = dict(raw)
                record.pop("schemas", None)
                if include_members and record.get("id"):
                    detail = self._client.get_json(
                        f"/pubapi/v2/groups/{record['id']}"
                    )
                    record["members"] = detail.get("members")
                else:
                    record.setdefault("members", None)
                record["egnyte_domain"] = self.domain
                yield record

        # ------------------------------------------------------------------ #
        # Links — partitioned on created_after / created_before
        # ------------------------------------------------------------------ #
        #
        # Table options:
        #   window_days      Partition width in days (default 7).
        #   start_timestamp  ISO lower bound for the very first read. Without it
        #                    the first run is one open-ended partition.
        #   page_size        Records per page (default 100, API max 500).
        #   link_path / link_type / accessibility  Server-side filters.

        def _link_partitions(
            self,
            table_options: dict[str, str],
            start_offset: dict | None,
            end_offset: dict | None,
        ) -> list[dict]:
            if start_offset is None and end_offset is None:
                start_iso = table_options.get("start_timestamp") or EPOCH_ISO
                end_iso = self._init_time
            else:
                start_iso = (
                    (start_offset or {}).get("cursor")
                    or table_options.get("start_timestamp")
                    or EPOCH_ISO
                )
                end_iso = (end_offset or {}).get("cursor") or self._init_time

            start_dt = parse_iso(start_iso)
            end_dt = parse_iso(end_iso)
            if start_dt >= end_dt:
                return []

            # First run: one unbounded-below partition rather than decades of
            # empty weekly windows.
            if start_dt <= parse_iso(FIRST_RUN_THRESHOLD_ISO):
                return [{"since": None, "until": format_iso(end_dt)}]

            window_days = parse_int(
                table_options.get("window_days"), DEFAULT_LINKS_WINDOW_DAYS, minimum=1
            )
            partitions: list[dict] = []
            cursor = start_dt
            while cursor < end_dt:
                nxt = min(cursor + timedelta(days=window_days), end_dt)
                partitions.append({"since": format_iso(cursor), "until": format_iso(nxt)})
                cursor = nxt
            return partitions

        def _read_links_window(
            self,
            since_iso: str | None,
            until_iso: str,
            table_options: dict[str, str],
        ) -> Iterator[dict]:
            """Read one ``[since, until)`` window of ``/pubapi/v2/links``.

            v2 is used over v1 deliberately: v1's list returns bare ids and needs
            a ``GET /links/{id}`` per row, while v2 returns full Link objects.

            ``created_after``/``created_before`` are passed through ``params`` so
            requests percent-encodes the ``+`` of the UTC offset as ``%2B`` — the
            doc calls that out as a real gotcha for hand-built query strings.

            The window is treated as half-open client-side (``since <= creation
            < until``) because Egnyte's own bound inclusivity is not documented;
            without that, adjacent windows would double-count boundary rows in an
            append-only table.
            """
            page_size = min(
                MAX_LINKS_PAGE_SIZE,
                parse_int(
                    table_options.get("page_size"), DEFAULT_LINKS_PAGE_SIZE, minimum=1
                ),
            )
            since_dt = parse_iso(since_iso) if since_iso else None
            until_dt = parse_iso(until_iso)

            params: dict[str, Any] = {
                "count": page_size,
                "created_before": api_timestamp(until_dt),
            }
            if since_dt is not None:
                params["created_after"] = api_timestamp(since_dt)
            for option_key, param_key in (
                ("link_path", "path"),
                ("link_type", "type"),
                ("accessibility", "accessibility"),
            ):
                if table_options.get(option_key):
                    params[param_key] = table_options[option_key]

            offset = 0
            for _ in range(MAX_PAGES_PER_READ):
                body = self._client.get_json(
                    "/pubapi/v2/links", params={**params, "offset": offset}
                )
                batch = records_from(body, ("links", "results", "resources", "ids"))
                if not batch:
                    break

                for raw in batch:
                    if not isinstance(raw, dict):
                        continue
                    created = parse_optional_iso(raw.get("creation_date"))
                    if created is not None:
                        if since_dt is not None and created < since_dt:
                            continue
                        if created >= until_dt:
                            continue
                    record = dict(raw)
                    record["egnyte_domain"] = self.domain
                    yield record

                offset += len(batch)
                total = parse_optional_int(body.get("total_count"))
                if total is not None and offset >= total:
                    break
                if len(batch) < page_size:
                    break

        # ------------------------------------------------------------------ #
        # Events — sequential id cursor
        # ------------------------------------------------------------------ #
        #
        # Table options:
        #   events_api_version  "v1" (default) or "v2" (adds permission_change).
        #   events_page_size    Events per call (default 100).
        #   start_event_id      Bootstrap cursor; defaults to the retained oldest.
        #   event_type / folder / suppress   Server-side filters.
        #   max_records_per_batch            Microbatch cap (full pages only).

        def _events_path(self, table_options: dict[str, str], suffix: str = "") -> str:
            version = table_options.get(
                "events_api_version", DEFAULT_EVENTS_API_VERSION
            ).strip().lower()
            if version not in ("v1", "v2"):
                version = DEFAULT_EVENTS_API_VERSION
            return f"/pubapi/{version}/events{suffix}"

        def _events_cursor_info(self, table_options: dict[str, str]) -> dict:
            """Fetch (and memoize) ``/events/cursor`` for this connector instance."""
            cached = self.__dict__.get("_events_cursor_cache")
            if cached is None:
                cached = self._client.get_json(
                    self._events_path(table_options, "/cursor")
                )
                self.__dict__["_events_cursor_cache"] = cached
            return cached

        def _events_latest_id(self, table_options: dict[str, str]) -> int | None:
            """The init-time high-water event id — this table's termination cap."""
            info = self._events_cursor_info(table_options)
            return parse_optional_int(info.get("latest_event_id"))

        def _events_oldest_id(self, table_options: dict[str, str]) -> int:
            info = self._events_cursor_info(table_options)
            oldest = parse_optional_int(info.get("oldest_event_id"))
            # `id` means "everything strictly after this", so step one back to
            # include the oldest retained event itself.
            return max(0, (oldest - 1)) if oldest is not None else 0

        def _read_events(
            self, start_offset: dict | None, table_options: dict[str, str]
        ) -> tuple[Iterator[dict], dict]:
            """Read forward from the stored event id.

            Append-only, so pages are never truncated client-side: we stop issuing
            *further* calls once ``max_records_per_batch`` is reached and let the
            last page land whole. Truncating would re-deliver the tail on the next
            run as permanent duplicates.

            Retention is 30 days (300K or 500K events depending on which Egnyte
            page you read), and a cursor that ages out answers ``404``. Per
            official guidance that is recovered by re-reading ``/events/cursor``
            and resuming from ``oldest_event_id``, accepting the gap.
            """
            start_offset = start_offset or {}
            cursor = parse_optional_int(start_offset.get("cursor"))
            if cursor is None:
                cursor = parse_optional_int(table_options.get("start_event_id"))
            if cursor is None:
                cursor = self._events_oldest_id(table_options)

            cap = self._events_latest_id(table_options)
            if cap is not None and cursor >= cap:
                # Caught up to the init-time snapshot — end_offset == start_offset.
                return iter([]), {"cursor": cursor}

            page_size = parse_int(
                table_options.get("events_page_size"),
                DEFAULT_EVENTS_PAGE_SIZE,
                minimum=1,
            )
            max_records = parse_int(
                table_options.get("max_records_per_batch"),
                DEFAULT_MAX_RECORDS_PER_BATCH,
                minimum=1,
            )

            base_params: dict[str, Any] = {"count": page_size}
            for option_key, param_key in (
                ("event_type", "type"),
                ("folder", "folder"),
                ("suppress", "suppress"),
            ):
                if table_options.get(option_key):
                    base_params[param_key] = table_options[option_key]

            endpoint = self._events_path(table_options)
            records: list[dict] = []
            recovered = False

            while len(records) < max_records:
                response = self._client.get_raw(
                    endpoint,
                    params={**base_params, "id": cursor},
                    expected=(200, 204, 404),
                )
                if response.status_code == 204:
                    break  # documented "no new events", not an error
                if response.status_code == 404:
                    if recovered:
                        break
                    # Cursor fell outside the retention window.
                    self.__dict__.pop("_events_cursor_cache", None)
                    recovered = True
                    cursor = self._events_oldest_id(table_options)
                    _LOG.warning(
                        "Egnyte events cursor aged out; resuming from oldest "
                        "retained event id %s (a gap in coverage is expected)",
                        cursor,
                    )
                    continue

                body = response.json() if (response.content or b"").strip() else {}
                batch = body.get("events") or []
                if not batch:
                    break

                for raw in batch:
                    record = dict(raw)
                    record["egnyte_domain"] = self.domain
                    records.append(record)

                batch_max = max(
                    (parse_optional_int(e.get("id")) or cursor) for e in batch
                )
                if batch_max <= cursor:
                    break  # server is not advancing; avoid an infinite loop
                cursor = batch_max

                latest_id = parse_optional_int(body.get("latest_id"))
                if latest_id is not None and cursor >= latest_id:
                    break
                if cap is not None and cursor >= cap:
                    break

            end_offset = {"cursor": cursor}
            if start_offset == end_offset:
                return iter([]), start_offset
            return iter(records), end_offset

        # ------------------------------------------------------------------ #
        # Audit reporting v1 — job-based, partitioned by date window
        # ------------------------------------------------------------------ #
        #
        # Table options:
        #   window_days                   Days per report job (default 7).
        #   initial_backfill_days         First-run lookback (default 7).
        #   start_date                    Explicit YYYY-MM-DD first-run start.
        #   audit_page_size               Report rows per fetch (default 100).
        #   audit_poll_interval_seconds   Job poll spacing (default 120).
        #   audit_poll_max_attempts       Poll attempts before giving up (30).
        #   audit_events / audit_folders / audit_users / audit_transaction_types /
        #   audit_assigners / audit_assignee_users / audit_assignee_groups
        #                                 Per-report-type filters (comma lists).
        #
        # Requires an admin or "can run reports" power user — a standard-user
        # token gets 403 here even though it works fine elsewhere.
        #
        # v2 (`/pubapi/v2/audit/stream`) is deliberately NOT used: it only serves
        # the trailing 7 days and carries its own 10/min, 100/hour limit, so it
        # cannot backfill. It stays a future low-latency add-on, not a
        # replacement.

        def _audit_partitions(
            self,
            table_options: dict[str, str],
            start_offset: dict | None,
            end_offset: dict | None,
        ) -> list[dict]:
            """Split into whole-calendar-day report windows.

            Offsets are dates, and ``date_end`` is inclusive, so windows tile the
            range with no overlap and no gap — which matters because audit rows
            are append-only with no server-assigned id to dedup on.
            """
            end_date_str = (end_offset or {}).get("date") or self._audit_cap_date
            end_date = parse_date(end_date_str)  # exclusive

            start_raw = (start_offset or {}).get("date") if start_offset else None
            if not start_raw:
                start_raw = table_options.get("start_date")
            if start_raw:
                start_date = parse_date(start_raw)
            else:
                backfill = parse_int(
                    table_options.get("initial_backfill_days"),
                    DEFAULT_AUDIT_BACKFILL_DAYS,
                    minimum=1,
                )
                start_date = end_date - timedelta(days=backfill)

            if start_date >= end_date:
                return []

            window_days = parse_int(
                table_options.get("window_days"), DEFAULT_AUDIT_WINDOW_DAYS, minimum=1
            )
            partitions: list[dict] = []
            cursor = start_date
            while cursor < end_date:
                window_end = min(cursor + timedelta(days=window_days), end_date)
                partitions.append(
                    {
                        "date_start": format_date(cursor),
                        # date_end is inclusive on the API.
                        "date_end": format_date(window_end - timedelta(days=1)),
                    }
                )
                cursor = window_end
            return partitions

        def _read_audit_window(
            self, table_name: str, partition: dict, table_options: dict[str, str]
        ) -> Iterator[dict]:
            """Delegate one date window to the audit job lifecycle (egnyte_audit)."""
            yield from read_audit_window(
                self._client,
                self.domain,
                AUDIT_TABLE_TYPES[table_name],
                partition["date_start"],
                partition["date_end"],
                table_options,
            )


    ########################################################
    # src/databricks/labs/community_connector/sparkpds/lakeflow_datasource.py
    ########################################################

    LakeflowConnectImpl = EgnyteLakeflowConnect
    # Constant option or column names
    METADATA_TABLE = "_community_table_metadata"
    NAMESPACES_TABLE = "_community_namespaces"
    TABLES_TABLE = "_community_tables"
    VIRTUAL_TABLES = (METADATA_TABLE, NAMESPACES_TABLE, TABLES_TABLE)
    TABLE_NAME = "tableName"
    TABLE_NAME_LIST = "tableNameList"
    TABLE_CONFIGS = "tableConfigs"
    IS_DELETE_FLOW = "isDeleteFlow"
    NAMESPACE_PREFIX = "namespacePrefix"
    NAMESPACE = "namespace"


    def _decode_list_of_str_option(option_name: str, value: str | None) -> list[str] | None:
        """Decode and validate a JSON-encoded ``list[str]`` Spark option.

        Returns ``None`` if the option is absent; otherwise the parsed list.
        Raises ``ValueError`` with the offending value if the JSON is malformed
        or the decoded value is not a list of strings.
        """
        if value is None:
            return None
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, list) or not all(isinstance(s, str) for s in decoded):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded list[str]; "
                f"got: {decoded!r}"
            )
        return decoded


    def _decode_dict_option(option_name: str, value: str | None) -> dict:
        """Decode and validate a JSON-encoded ``dict`` Spark option."""
        if value is None:
            return {}
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError as e:
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; "
                f"got non-JSON value: {value!r}"
            ) from e
        if not isinstance(decoded, dict):
            raise ValueError(
                f"option '{option_name}' must be a JSON-encoded dict; got: {decoded!r}"
            )
        return decoded


    # PySpark's DataSource API requires camelCase method names and inherits
    # semantics from the parent class, so per-method docstrings are redundant.
    # pylint: disable=invalid-name,missing-function-docstring
    class LakeflowStreamReader(SimpleDataSourceStreamReader, SupportsTriggerAvailableNow):
        """
        Implements a data source stream reader for Lakeflow Connect.
        Currently, only the simpleStreamReader is implemented, which uses a
        more generic protocol suitable for most data sources that support
        incremental loading.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.lakeflow_connect = lakeflow_connect
            self.schema = schema

        def initialOffset(self):
            return {}

        def read(self, start: dict) -> (Iterator[tuple], dict):
            is_delete_flow = self.options.get(IS_DELETE_FLOW) == "true"
            # Strip delete flow options before passing to connector
            table_options = {
                k: v for k, v in self.options.items() if k != IS_DELETE_FLOW
            }

            if is_delete_flow:
                records, offset = self.lakeflow_connect.read_table_deletes(
                    self.options[TABLE_NAME], start, table_options
                )
            else:
                records, offset = self.lakeflow_connect.read_table(
                    self.options[TABLE_NAME], start, table_options
                )
            rows = map(lambda x: parse_value(x, self.schema), records)
            return rows, offset

        def readBetweenOffsets(self, start: dict, end: dict) -> Iterator[tuple]:
            # TODO: This does not ensure the records returned are identical across repeated calls.
            # For append-only tables, the data source must guarantee that reading from the same
            # start offset will always yield the same set of records.
            # For tables ingested as incremental CDC, it is only necessary that no new changes
            # are missed in the returned records.
            return self.read(start)[0]

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowPartitionedStreamReader(DataSourceStreamReader, SupportsTriggerAvailableNow):
        """Proxy that bridges SupportsPartitionedStream to PySpark's DataSourceStreamReader.

        Used when a connector implements the SupportsPartitionedStream mixin to
        support partitioned streaming reads across Spark executors.
        """

        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self.table_options = {k: v for k, v in options.items() if k != IS_DELETE_FLOW}

        def initialOffset(self):
            return {}

        def getDefaultReadLimit(self):
            # Admission control is the connector's responsibility (e.g. via
            # window_days, max_records_per_batch), not the engine's.  Always
            # ask the engine for ReadAllAvailable.
            return ReadAllAvailable()

        def latestOffset(self, start: dict, limit) -> dict:
            # We declared ReadAllAvailable via getDefaultReadLimit; the engine
            # must respect it.  Anything else means admission-control expectations
            # we do not support — fail loudly rather than silently ignore.
            if not isinstance(limit, ReadAllAvailable):
                raise ValueError(
                    f"LakeflowPartitionedStreamReader only supports ReadAllAvailable; "
                    f"got {type(limit).__name__}. Micro-batch sizing must be controlled "
                    f"by the connector implementation (table_options), not the engine."
                )
            return self.lakeflow_connect.latest_offset(
                self.table_name, self.table_options, start
            )

        def partitions(self, start: dict, end: dict):
            partition_descs = self.lakeflow_connect.get_partitions(
                self.table_name, self.table_options, start, end
            )
            return [InputPartition(json.dumps(p)) for p in partition_descs]

        def read(self, partition: InputPartition):
            partition_desc = json.loads(partition.value)
            records = self.lakeflow_connect.read_partition(
                self.table_name, partition_desc, self.table_options
            )
            return map(lambda x: parse_value(x, self.schema), records)

        def prepareForTriggerAvailableNow(self) -> None:
            # No need to do anything special here. Everything is handled in the __init__ method.
            pass


    class LakeflowBatchReader(DataSourceReader):
        def __init__(
            self,
            options: dict[str, str],
            schema: StructType,
            lakeflow_connect: LakeflowConnect,
        ):
            self.options = options
            self.schema = schema
            self.lakeflow_connect = lakeflow_connect
            self.table_name = options[TABLE_NAME]
            self._supports_partition = isinstance(lakeflow_connect, SupportsPartition)

        def partitions(self):
            if self._supports_partition and self.table_name not in VIRTUAL_TABLES:
                try:
                    partition_descs = self.lakeflow_connect.get_partitions(
                        self.table_name, self.options
                    )
                    return [InputPartition(json.dumps(p)) for p in partition_descs]
                except Exception:
                    self._supports_partition = False
            return [InputPartition(None)]

        def read(self, partition):
            if self.table_name == METADATA_TABLE:
                records = self._read_table_metadata()
            elif self.table_name == NAMESPACES_TABLE:
                records = self._read_namespaces()
            elif self.table_name == TABLES_TABLE:
                records = self._read_tables()
            elif self._supports_partition and partition.value is not None:
                partition_desc = json.loads(partition.value)
                records = self.lakeflow_connect.read_partition(
                    self.table_name, partition_desc, self.options
                )
            else:
                records, _ = self.lakeflow_connect.read_table(self.table_name, None, self.options)
            return map(lambda x: parse_value(x, self.schema), records)

        def _read_table_metadata(self):
            table_names = _decode_list_of_str_option(
                TABLE_NAME_LIST, self.options.get(TABLE_NAME_LIST)
            ) or []
            table_configs = _decode_dict_option(
                TABLE_CONFIGS, self.options.get(TABLE_CONFIGS)
            )
            all_records = []
            # Preserve caller-supplied table order — caller controls it.
            for table in table_names:
                metadata = self.lakeflow_connect.read_table_metadata(
                    table, table_configs.get(table, {})
                )
                all_records.append({TABLE_NAME: table, **metadata})
            return all_records

        def _read_namespaces(self):
            # Connectors without SupportsNamespaces are flat — no rows.
            if not isinstance(self.lakeflow_connect, SupportsNamespaces):
                return []
            prefix = _decode_list_of_str_option(
                NAMESPACE_PREFIX, self.options.get(NAMESPACE_PREFIX)
            )
            namespaces = self.lakeflow_connect.list_namespaces(prefix)
            # Sort framework-side for deterministic output regardless of
            # connector iteration order.
            return [{"namespace": ns} for ns in sorted(namespaces)]

        def _read_tables(self):
            namespace_supplied = NAMESPACE in self.options
            if isinstance(self.lakeflow_connect, SupportsNamespaces):
                if not namespace_supplied:
                    raise ValueError(
                        f"option '{NAMESPACE}' is required when reading "
                        f"'{TABLES_TABLE}' against a connector that implements "
                        f"SupportsNamespaces. Pass a JSON-encoded list[str] "
                        f"(use '[]' for root-level tables; walk the tree via "
                        f"'{NAMESPACES_TABLE}' to enumerate every namespace)."
                    )
                namespace = _decode_list_of_str_option(
                    NAMESPACE, self.options[NAMESPACE]
                )
                tables = self.lakeflow_connect.list_tables_in_namespace(namespace)
                return [
                    {"namespace": namespace, TABLE_NAME: tn}
                    for tn in sorted(tables)
                ]
            # Flat connector path. Reject a stray `namespace` option — the
            # caller probably mistook this connector for namespace-aware and
            # silently ignoring the option would mask the bug.
            if namespace_supplied:
                raise ValueError(
                    f"option '{NAMESPACE}' was supplied but the connector does "
                    f"not implement SupportsNamespaces. Either omit the option "
                    f"or use a namespace-aware connector."
                )
            return [
                {"namespace": [], TABLE_NAME: tn}
                for tn in sorted(self.lakeflow_connect.list_tables())
            ]


    class LakeflowSource(DataSource):
        """
        PySpark DataSource base for Lakeflow Connect.

        Two ways the connector implementation is bound:

        - Per-source subclass (wheel / multi-file deployment): subclass and set
          ``_lakeflow_connect_cls``::

              class GmailDataSource(LakeflowSource):
                  _lakeflow_connect_cls = GmailLakeflowConnect

              spark.dataSource.register(GmailDataSource)

        - Merged single-file deployment (SDP): ``_lakeflow_connect_cls`` is left
          ``None`` and the connector is taken from the module-level
          ``LakeflowConnectImpl`` placeholder, which the merge script substitutes
          with the actual implementation class.
        """

        # Per-source subclasses set this. Left ``None`` on the base so the merged
        # single-file path falls back to the ``LakeflowConnectImpl`` placeholder.
        _lakeflow_connect_cls = None

        # Spark format name. Defaults to "lakeflow_connect" because Unity Catalog
        # connection-option injection looks for that exact string. A per-source
        # subclass may override this with its source name once it no longer relies
        # on UC injection (see the commented override in each source's __init__.py).
        _format_name = "lakeflow_connect"

        def __init__(self, options):
            self.options = options
            table = options.get(TABLE_NAME)
            # Catch typos against the framework's reserved virtual-table namespace
            # early — falling through to the connector with an unknown
            # `_community_*` name yields a confusing per-connector error.
            if table and table.startswith("_community_") and table not in VIRTUAL_TABLES:
                raise ValueError(
                    f"unknown framework virtual table '{table}'. Valid framework "
                    f"virtual tables are: {', '.join(VIRTUAL_TABLES)}. "
                    f"For a regular source table, use a name that does not start "
                    f"with '_community_'."
                )
            # Per-source subclasses bind the implementation via _lakeflow_connect_cls.
            # The merged single-file path leaves it None and relies on the
            # LakeflowConnectImpl placeholder (substituted by the merge script).
            connect_cls = type(self)._lakeflow_connect_cls or LakeflowConnectImpl
            self.lakeflow_connect = connect_cls(options)  # pylint: disable=abstract-class-instantiated

        @classmethod
        def name(cls):
            return cls._format_name

        def schema(self):
            table = self.options[TABLE_NAME]
            if table == METADATA_TABLE:
                return StructType(
                    [
                        StructField(TABLE_NAME, StringType(), False),
                        StructField("primary_keys", ArrayType(StringType()), True),
                        StructField("cursor_field", StringType(), True),
                        StructField("ingestion_type", StringType(), True),
                    ]
                )
            if table == NAMESPACES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                    ]
                )
            if table == TABLES_TABLE:
                return StructType(
                    [
                        StructField("namespace", ArrayType(StringType()), False),
                        StructField(TABLE_NAME, StringType(), False),
                    ]
                )
            return self.lakeflow_connect.get_table_schema(table, self.options)

        def reader(self, schema: StructType):
            return LakeflowBatchReader(self.options, schema, self.lakeflow_connect)

        def streamReader(self, schema: StructType):
            # Use the partitioned DataSourceStreamReader when the connector
            # implements SupportsPartitionedStream and the table opts in.
            # Otherwise, delegate to super() which raises PySparkNotImplementedError,
            # causing Spark to fall back to simpleStreamReader().
            if isinstance(self.lakeflow_connect, SupportsPartitionedStream):
                table = self.options[TABLE_NAME]
                if self.lakeflow_connect.is_partitioned(table):
                    return LakeflowPartitionedStreamReader(self.options, schema, self.lakeflow_connect)
            return super().streamReader(schema)

        def simpleStreamReader(self, schema: StructType):
            return LakeflowStreamReader(self.options, schema, self.lakeflow_connect)


    spark.dataSource.register(LakeflowSource)
